// Product hub: finds the tools and renders cards on the homepage and the tools directory.
// 1) tries the live API (server.js) so new folders appear within seconds,
// 2) falls back to tools/manifest.js (generated by build.js) on static hosting / file://.
(function () {
  const root = (window.PZ && PZ.root) || '';
  const hub = document.getElementById('hub');
  if (!hub) return;
  const limit = parseInt(hub.dataset.limit || '0', 10);
  const q = document.getElementById('q'), catsEl = document.getElementById('cats'), emptyEl = document.getElementById('empty');
  const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const LABEL = { live: 'Live', beta: 'Beta', soon: 'Coming soon' };
  let tools = [], live = false, last = '', cat = 'All', first = true;

  async function load() {
    try {
      const r = await fetch(root + 'api/tools', { cache: 'no-store' });
      if (r.ok && (r.headers.get('content-type') || '').includes('json')) { live = true; return await r.json(); }
    } catch (e) { /* no live API: static hosting */ }
    live = false;
    return window.PUZZLES_TOOLS || [];
  }

  function card(t, i) {
    const base = root + 'tools/' + encodeURIComponent(t.slug) + '/';
    const img = t.thumbnail ? `<img src="${base}${esc(t.thumbnail)}" alt="" loading="lazy" onerror="this.remove()">` : '';
    const inner = `<div class="thumb"><div class="ph">${esc(t.icon)}</div>${img}<span class="badge ${t.status}">${LABEL[t.status]}</span></div>
      <div class="body"><span class="cat">${esc(t.category)}</span><h3>${esc(t.name)}</h3>
      ${t.tagline ? `<p class="tag">${esc(t.tagline)}</p>` : ''}${t.description ? `<p class="desc">${esc(t.description)}</p>` : ''}
      ${t.tags.length ? `<div class="chips">${t.tags.slice(0, 4).map(x => `<span>${esc(x)}</span>`).join('')}</div>` : ''}
      <span class="go">${t.status === 'soon' ? 'Coming soon' : 'Open tool <i>→</i>'}</span></div>`;
    const d = `style="--d:${Math.min(i, 8) * 70}ms"`;
    return t.status === 'soon' ? `<div class="card soon reveal" ${d}>${inner}</div>` : `<a class="card reveal" ${d} href="${base}">${inner}</a>`;
  }

  function render() {
    const term = q ? q.value.trim().toLowerCase() : '';
    let list = tools.filter(t => (cat === 'All' || t.category === cat) &&
      (!term || [t.name, t.tagline, t.description, t.category, ...t.tags].join(' ').toLowerCase().includes(term)));
    if (limit) list = list.slice(0, limit);
    hub.innerHTML = list.map(card).join('');
    if (emptyEl) emptyEl.classList.toggle('show', !list.length);
    PZ.reveal(hub);
  }

  function renderCats() {
    if (!catsEl) return;
    const cs = ['All', ...new Set(tools.map(t => t.category))];
    if (!cs.includes(cat)) cat = 'All';
    catsEl.innerHTML = cs.map(c => `<button class="${c === cat ? 'on' : ''}" data-c="${esc(c)}">${esc(c)}</button>`).join('');
  }

  function stats() {
    const n = document.getElementById('stat-tools');
    if (n) n.textContent = tools.filter(t => t.status !== 'soon').length;
  }

  async function refresh() {
    const t = await load(), sig = JSON.stringify(t);
    if (sig === last) return;
    last = sig; tools = t; stats(); renderCats(); render();
    first = false;
  }

  if (q) q.addEventListener('input', render);
  if (catsEl) catsEl.addEventListener('click', e => {
    const b = e.target.closest('button[data-c]'); if (!b) return;
    cat = b.dataset.c; renderCats(); render();
  });

  hub.innerHTML = '<div class="sk"></div><div class="sk"></div><div class="sk"></div>';
  refresh().then(() => { if (live) setInterval(refresh, 8000); });   // pick up new tool folders automatically
})();
